const lessons = context.workflow['COUNT_LESSONS'].result?.metadata?.total || 0;
const topics = context.workflow['COUNT_TOPICS'].result?.metadata?.total || 0;
return topics > 0 && lessons === 0;

topic_id.code:
const item = context.workflow['LOOP_LESSONS'].loop?.item || {};
const allTopics = context.workflow['FETCH_TOPICS']?.result?.data || [];
const match = allTopics.find(function(t) { return t.code === item.topic_code; });
return match?.id || '';

